// Construit la requête d'extraction envoyée au modèle
const p = $('Paramètres mission').first().json;
const out = [];

for (const item of $input.all()) {
  const cvText = (item.json.text || '').slice(0, 60000);

  const systemPrompt = `Tu es un assistant de recrutement. Tu lis un CV brut et tu renvoies UNIQUEMENT un objet JSON valide, sans texte autour, sans balises markdown.

Schéma exact à respecter :
{
  "nom": string|null,
  "email": string|null,
  "telephone": string|null,
  "ville": string|null,
  "code_postal": string|null,
  "permis": boolean|null,
  "vehicule": boolean|null,
  "metier_principal": string|null,
  "domaine_activite": string|null,
  "competences": string[],
  "annees_experience": number|null,
  "diplomes": string[],
  "habilitations": string[],
  "visite_medicale_a_jour": boolean|null,
  "dispo_immediate": boolean|null,
  "date_disponibilite": string|null,
  "nb_missions_similaires": number|null,
  "resume": string
}

Règles :
- Si une information n'apparaît pas dans le CV, mets null (ou [] pour les listes). N'invente jamais.
- "resume" = 2 phrases maximum décrivant le profil.
- "habilitations" = CACES, habilitations électriques, SST, certifications, etc., recopiées telles quelles.`;

  const userPrompt = `Mission visée : ${p.intitulePoste} (domaine : ${p.domaine})

CV à analyser :
"""
${cvText}
"""`;

  out.push({
    json: {
      emailExpediteur: item.json.from || null,
      nomFichier: item.binary?.attachment_0?.fileName || null,
      payload: {
        model: 'claude-sonnet-5',
        max_tokens: 2000,
        system: systemPrompt,
        messages: [{ role: 'user', content: userPrompt }]
      }
    }
  });
}

return out;

// Scoring : critères bloquants puis note pondérée sur 100
const p = $('Paramètres mission').first().json;
const prep = $('Préparer l\'analyse').all();
const out = [];

const toList = (s) => (s || '').split(',').map(x => x.trim().toLowerCase()).filter(Boolean);
const norm = (s) => (s || '').toString().toLowerCase();
const has = (arr, needle) => (arr || []).some(x => norm(x).includes(needle) || needle.includes(norm(x)));

const competencesAttendues = toList(p.competencesAttendues);
const habilitationsObligatoires = toList(p.habilitationsObligatoires);
const villesAcceptees = toList(p.villesAcceptees);
const diplomesSouhaites = toList(p.diplomeSouhaite);
const diplomesObligatoires = toList(p.diplomeReglementaireObligatoire);

$input.all().forEach((item, i) => {
  const meta = prep[i]?.json || {};
  const raw = item.json?.content?.[0]?.text || '';

  let c = null;
  try {
    c = JSON.parse(raw.replace(/```json/gi, '').replace(/```/g, '').trim());
  } catch (e) { /* parsing échoué */ }

  if (!c) {
    out.push({ json: {
      date: new Date().toISOString(),
      fichier: meta.nomFichier, statut: 'À traiter manuellement',
      score: 0, motifs: 'Extraction IA illisible', reponse_brute: raw.slice(0, 500)
    }});
    return;
  }

  // ---- 1. Critères bloquants ----
  const motifsRejet = [];

  for (const h of habilitationsObligatoires) {
    if (!has(c.habilitations, h)) motifsRejet.push(`Habilitation manquante : ${h}`);
  }
  for (const d of diplomesObligatoires) {
    if (!has(c.diplomes, d)) motifsRejet.push(`Diplôme réglementaire manquant : ${d}`);
  }
  if (p.visiteMedicaleRequise && c.visite_medicale_a_jour === false) {
    motifsRejet.push('Visite médicale non à jour');
  }
  if (p.permisRequis && c.permis === false) motifsRejet.push('Permis requis absent');
  if (p.vehiculeRequis && c.vehicule === false) motifsRejet.push('Véhicule requis absent');

  // ---- 2. Points de vigilance (n'écartent pas automatiquement) ----
  const vigilance = [];
  if (villesAcceptees.length && c.ville && !villesAcceptees.some(v => norm(c.ville).includes(v))) {
    vigilance.push(`Localisation à vérifier (${c.ville})`);
  }
  if (p.visiteMedicaleRequise && c.visite_medicale_a_jour === null) vigilance.push('Visite médicale non mentionnée');
  if (p.vehiculeRequis && c.vehicule === null) vigilance.push('Véhicule non mentionné');
  if (!c.email && !c.telephone) vigilance.push('Aucun contact trouvé sur le CV');

  // ---- 3. Score pondéré ----
  const detail = {};

  const matched = competencesAttendues.filter(k => has(c.competences, k) || norm(c.metier_principal).includes(k));
  detail.competences = competencesAttendues.length ? Math.round((matched.length / competencesAttendues.length) * 30) : 30;

  const exp = Number(c.annees_experience) || 0;
  const cible = Number(p.experienceCibleAnnees) || 1;
  detail.experience = Math.round(Math.min(exp / cible, 1) * 20);

  const dom = norm(p.domaine);
  if (dom && norm(c.domaine_activite).includes(dom)) detail.domaine = 20;
  else if (dom && norm(c.metier_principal).includes(dom)) detail.domaine = 12;
  else detail.domaine = 0;

  detail.disponibilite = c.dispo_immediate === true ? 10 : (c.date_disponibilite ? 5 : 0);

  detail.diplome = diplomesSouhaites.some(d => has(c.diplomes, d)) ? 10 : 0;

  const nb = Number(c.nb_missions_similaires) || 0;
  detail.historique = nb >= 3 ? 10 : (nb >= 1 ? 6 : 0);

  const score = Object.values(detail).reduce((a, b) => a + b, 0);

  // ---- 4. Statut final ----
  let statut;
  if (motifsRejet.length) statut = 'Écarté (critère bloquant)';
  else if (score >= p.seuilRetenu) statut = 'Retenu';
  else if (score >= p.seuilARevoir) statut = 'À revoir';
  else statut = 'Écarté (score insuffisant)';

  out.push({ json: {
    date: new Date().toISOString(),
    fichier: meta.nomFichier,
    email_expediteur: meta.emailExpediteur,
    nom: c.nom, email: c.email, telephone: c.telephone, ville: c.ville,
    metier: c.metier_principal,
    experience_annees: exp,
    habilitations: (c.habilitations || []).join(' | '),
    diplomes: (c.diplomes || []).join(' | '),
    disponibilite: c.dispo_immediate ? 'Immédiate' : (c.date_disponibilite || 'Non précisée'),
    score,
    detail_score: JSON.stringify(detail),
    statut,
    motifs: motifsRejet.join(' ; '),
    vigilance: vigilance.join(' ; '),
    resume: c.resume,
    mission: p.intitulePoste
  }});
});

return out;

